            "(переключатель в меню).\n"
            "«Только нерусским клиентам» — вопрос кнопками при первом /start показывается "
            "только делегатам, чей Telegram-клиент не на русском.\n"
            "«Всем при первом /start» — вопрос кнопками показывается КАЖДОМУ новому делегату "
