# ── Квик 260927: рейтинг чата делегатов — числа берутся из chat_score, второго источника нет ──
# Группа "chat" («💬 Чат делегатов», раздел «🔧 Управление»). Веса формулы — глобальные (одна
# калиброванная формула на все города); режим и суммы правил города — per_city, их правит экран
# «🏆 Рейтинг чата» (handlers/chat/admin_chat_rating.py). Дефолт режима — «формула»: при выкатке ни
# один город не меняет поведение; дефолты правил — пресет СПб (организатор, 27.09).
# Суммы и веса — type "text" + "format": "number" (дробь через запятую, 0 допустим): "int"-ветка
# `_parse_setting` превращает 0 в дефолт, а для весов 0 — осмысленное «не учитывать».
# Потребители (дашборд, экран бота) читают СЫРЫЕ значения через chat_score.weights_from_settings
# / rules_from_settings — те и разбирают «0» как 0 (в том числе у *_max, которые здесь "int").


def _chat_num(value) -> str:
    """Дефолт в подсказке — как менеджер его наберёт: «0,5», а не «0.5»."""
    return f"{value:g}".replace(".", ",")


def _chat_weight(name: str, label: str, what: str, **extra) -> dict:
    default = chat_score.WEIGHTS[name]
    entry = {
        "type": "text", "format": "number", "group": "chat", "label": label,
        "prompt": f"{what}\n\nПо умолчанию {_chat_num(default)}.",
        "default": f"{default:g}",
    }
    entry.update(extra)
    return entry


def _chat_rule(name: str, label: str, what: str) -> dict:
    default = chat_score.RULES_DEFAULTS[name]
    is_int = name.endswith(("_chars", "_max"))
    entry = {
        "type": "int" if is_int else "text", "group": "chat", "label": label,
        "prompt": f"{what}\n\nПо умолчанию {_chat_num(default)}.",
        "default": default if is_int else f"{default:g}",
        "per_city": True,
    }
    if not is_int:
        entry["format"] = "number"
    return entry


